export default function event({ body }) {
  const e = body?.event ?? body,
    p = e?.project?.path_with_namespace,
    a = e?.object_attributes,
    i = a?.iid,
    commit = a?.last_commit?.id;
  if (
    e?.object_kind !== "merge_request" ||
    typeof p !== "string" ||
    !p ||
    !Number.isInteger(i) ||
    i < 1 ||
    typeof commit !== "string" ||
    !commit
  )
    throw Error("Invalid merge request event");
  const base = "/projects/" + encodeURIComponent(p) + "/merge_requests/" + i;
  return {
    event: {
      project: p,
      iid: i,
      commit,
      author: a?.last_commit?.author?.email ?? "",
      user: e?.user?.name ?? "",
      name: e?.project?.name ?? p,
    },
    endpoint: base + "/changes",
    noteEndpoint: base + "/notes",
  };
}

