export default function diff({ body, statusCode, bodyEncoding, event }) {
  if (
    statusCode !== 200 ||
    bodyEncoding ||
    !Array.isArray(body?.changes) ||
    typeof body.web_url !== "string"
  )
    throw Error("Invalid merge request changes");
  if (body.iid !== event.iid) throw Error("Merge request mismatch");
  return {
    changed: body.changes.length > 0,
    diff: JSON.stringify(
      body.changes.map((x) => ({ old_path: x.old_path, new_path: x.new_path, diff: x.diff })),
    ),
    url: body.web_url,
  };
}

