export default function recipients({ event, mapping, global }) {
  const specific = mapping[event.project] ?? [],
    all = [...specific, ...global, event.author].filter(Boolean);
  if (
    !all.length ||
    all.some((x) => typeof x !== "string" || !/^\S+@\S+\.\S+$/.test(x) || x.includes("YOUR_"))
  )
    throw Error("Configure recipients");
  return { to: [...new Set(all)].join(", ") };
}

