export default async function reserve({ event, operation, acknowledge, resolution }, ctx) {
  const key =
      "gitlab-review:" + event.project + ":" + event.iid + ":" + event.commit + ":" + operation,
    old = await ctx.state.get(key);
  if (old?.status === "done") return { key, write: false };
  if (old?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "done" });
      return { key, write: false };
    }
  }
  await ctx.state.set(key, { status: "pending" });
  return { key, write: true };
}

