export default async function f({ key, body, statusCode }, ctx) {
  if (statusCode < 200 || statusCode >= 300 || !body?.id)
    throw Error("Unknown GitLab comment result");
  await ctx.state.set(key, { status: "done" });
  return { ok: true };
}

